<article class="tool-card"><h3>3. URL Encoder / Decoder</h3><textarea id="durl" rows="3"></textarea><button class="button primary" onclick="document.getElementById('durlout').value=encodeURIComponent(document.getElementById('durl').value)">Encode</button><button class="button secondary" onclick="try{document.getElementById('durlout').value=decodeURIComponent(document.getElementById('durl').value)}catch(e){document.getElementById('durlout').value='Invalid encoding'}">Decode</button><textarea id="durlout" rows="3" readonly></textarea></article>
<article class="tool-card"><h3>4. HTML Entity Escaper</h3><textarea id="dhtml" rows="3" placeholder="<h1>Hello</h1>"></textarea><button class="button primary" onclick="document.getElementById('dhtmlout').value=document.getElementById('dhtml').value.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/&quot;/g,'&amp;quot;')">Escape HTML</button><textarea id="dhtmlout" rows="3" readonly></textarea></article>
<article class="tool-card"><h3>5. UUID Generator</h3><p id="duuid">Click generate to create a UUID.</p><button class="button primary" onclick="document.getElementById('duuid').textContent=crypto.randomUUID()">Generate UUID</button></article>
<article class="tool-card"><h3>6. Unix Timestamp Converter</h3><input id="dts" type="number" placeholder="Timestamp in seconds"/><button class="button primary" onclick="try{document.getElementById('dtsout').textContent=new Date(Number(document.getElementById('dts').value)*1000).toISOString()}catch(e){document.getElementById('dtsout').textContent='Enter a valid timestamp'}">Convert</button><p id="dtsout"></p><button class="button secondary" onclick="document.getElementById('dts').value=Math.floor(Date.now()/1000);document.getElementById('dts').dispatchEvent(new Event('input'))">Current timestamp</button></article>
