<article class="tool-card"><h3>8. HEX / RGB Color Converter</h3><input id="dc" type="color" value="#087ea4" oninput="let n=parseInt(this.value.slice(1),16);document.getElementById('dcout').textContent=this.value+' — RGB('+ (n>>16)+', '+(n>>8&255)+', '+(n&255)+')"/><p id="dcout">#087ea4</p></article>
<article class="tool-card"><h3>9. CSS Gradient Generator</h3><input id="dg1" type="color" value="#082b5b"/><input id="dg2" type="color" value="#12b8a6"/><input id="dga" type="range" min="0" max="360" value="135"/><button class="button primary" onclick="let s='linear-gradient('+document.getElementById('dga').value+'deg,'+document.getElementById('dg1').value+','+document.getElementById('dg2').value+')';document.getElementById('dgp').style.background=s;document.getElementById('dgo').value='background: '+s+';'">Create Gradient</button><div id="dgp" style="height:60px"></div><textarea id="dgo" rows="2" readonly></textarea></article>
