<article class="tool-card"><h3>12. Lorem Ipsum Generator</h3><input id="dloremn" type="number" min="1" max="10" value="3"/><button class="button primary" onclick="document.getElementById('dlorem').value=Array.from({length:Math.max(1,Math.min(10,+document.getElementById('dloremn').value||1))},()=> 'Lorem ipsum dolor sit amet, consectetur adipiscing elit. Integer posuere sapien vitae consequat gravida.').join('\n\n')">Generate Text</button><textarea id="dlorem" rows="4" readonly></textarea></article>
<article class="tool-card"><h3>13. Duplicate Line Remover</h3><textarea id="ddup" rows="3" placeholder="One item per line"></textarea><button class="button primary" onclick="document.getElementById('ddupout').value=[...new Set(document.getElementById('ddup').value.split('\n'))].join('\n')">Remove Duplicates</button><textarea id="ddupout" rows="3" readonly></textarea></article>
<article class="tool-card"><h3>14. Line Sorter</h3><textarea id="dsort" rows="3" placeholder="One item per line"></textarea><button class="button primary" onclick="document.getElementById('dsortout').value=document.getElementById('dsort').value.split('\n').sort((a,b)=>a.localeCompare(b)).join('\n')">Sort A–Z</button><textarea id="dsortout" rows="3" readonly></textarea></article>
