<article class="tool-card"><h3>16. JWT Payload Decoder</h3><textarea id="djwt" rows="3" placeholder="Paste JWT token"></textarea><button class="button primary" onclick="try{let p=document.getElementById('djwt').value.split('.')[1].replace(/-/g,'+').replace(/_/g,'/');document.getElementById('djwtout').textContent=JSON.stringify(JSON.parse(atob(p)),null,2)}catch(e){document.getElementById('djwtout').textContent='Invalid or unsupported token payload'}">Decode Payload</button><pre id="djwtout"></pre><small>Does not verify signature.</small></article>
<article class="tool-card"><h3>17. Query String Parser</h3><input id="dquery" placeholder="?name=MRK&role=developer"/><button class="button primary" onclick="document.getElementById('dqueryout').textContent=JSON.stringify(Object.fromEntries(new URLSearchParams(document.getElementById('dquery').value.replace(/^\?/,''))),null,2)">Parse Query</button><pre id="dqueryout"></pre></article>
<article class="tool-card"><h3>18. Markdown Plain-Text Preview</h3><textarea id="dmd" rows="3" placeholder="# Heading&#10;**Bold text**"></textarea><button class="button primary" onclick="document.getElementById('dmdout').textContent=document.getElementById('dmd').value.replace(/^#+\s/gm,'').replace(/\*\*(.*?)\*\*/g,'$1').replace(/^[-*]\s/gm,'• ')">Preview Text</button><pre id="dmdout"></pre></article>
<article class="tool-card"><h3>19. Number Base Converter</h3><input id="dnum" value="255"/><select id="dbase"><option value="10">Decimal</option><option value="2">Binary</option><option value="8">Octal</option><option value="16">Hexadecimal</option></select><button class="button primary" onclick="let n=parseInt(document.getElementById('dnum').value,+document.getElementById('dbase').value);document.getElementById('dnumout').textContent=Number.isNaN(n)?'Invalid input':'Binary: '+n.toString(2)+'\nOctal: '+n.toString(8)+'\nDecimal: '+n+'\nHex: '+n.toString(16)">Convert</button><pre id="dnumout"></pre></article>
<article class="tool-card"><h3>20. HTML Snippet Preview</h3><textarea id="dsnippet" rows="3" placeholder="<h2>Hello developer!</h2>"></textarea><button class="button primary" onclick="document.getElementById('dsnippetout').srcdoc=document.getElementById('dsnippet').value.replace(/<script\b[\s\S]*?<\/script\s*>/gi,'').replace(/\son\w+\s*=\s*('[^']*'|&quot;[^&]*&quot;|[^\s>]+)/gi,'')">Preview Snippet</button><iframe id="dsnippetout" sandbox="" title="Sandboxed HTML preview" style="width:100%;height:130px;background:white"></iframe><small>Scripts are removed and iframe is sandboxed.</small></article>
